/**
 * Hero graphic — a visual editor selecting an element on a page. Strokes draw
 * themselves in (global .m-draw + pathLength=1), the selection ring pulses, the
 * cursor drifts. Colors come from the .nco-motion theme vars. Generated by a
 * sub-agent, integrated + corrected (single clean cursor; no local style block).
 */

export default function HeroSelection() {
  return (
    <svg
      viewBox="0 0 640 480"
      width="100%"
      height="100%"
      role="img"
      aria-label="A visual editor selecting an element on a page"
      preserveAspectRatio="xMidYMid meet"
      style={{ display: 'block' }}
    >
      {/* Browser / viewport frame */}
      <g aria-hidden="true">
        <rect x={80} y={40} width={480} height={380} rx={6} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0s' }} />
        <line x1={80} y1={72} x2={560} y2={72} stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.05s' }} />
        <circle cx={104} cy={56} r={5} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} pathLength={1} className="m-draw" style={{ animationDelay: '0.1s' }} />
        <circle cx={120} cy={56} r={5} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} pathLength={1} className="m-draw" style={{ animationDelay: '0.13s' }} />
        <circle cx={136} cy={56} r={5} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} pathLength={1} className="m-draw" style={{ animationDelay: '0.16s' }} />
        <rect x={200} y={46} width={200} height={20} rx={3} fill="none" stroke="var(--m-line)" strokeWidth={1} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.18s' }} />
      </g>

      {/* Page content blocks */}
      <g aria-hidden="true">
        <rect x={112} y={96} width={200} height={14} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.28s' }} />
        <rect x={112} y={118} width={130} height={8} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.32s' }} />

        {/* left card */}
        <rect x={112} y={148} width={140} height={100} rx={4} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.38s' }} />
        <rect x={124} y={162} width={80} height={8} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.42s' }} />
        <rect x={124} y={178} width={104} height={6} rx={1} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.44s' }} />
        <rect x={124} y={216} width={56} height={18} rx={2} fill="none" stroke="var(--m-line)" strokeWidth={1} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.48s' }} />

        {/* right card */}
        <rect x={388} y={148} width={140} height={100} rx={4} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.50s' }} />
        <rect x={400} y={162} width={80} height={8} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.53s' }} />
        <rect x={400} y={178} width={104} height={6} rx={1} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.55s' }} />
        <rect x={400} y={216} width={56} height={18} rx={2} fill="none" stroke="var(--m-line)" strokeWidth={1} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.59s' }} />

        {/* footer blocks */}
        <rect x={112} y={272} width={416} height={6} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.62s' }} />
        <rect x={112} y={286} width={280} height={6} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.64s' }} />
        <rect x={112} y={308} width={416} height={80} rx={4} fill="none" stroke="var(--m-line)" strokeWidth={1} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.66s' }} />
      </g>

      {/* Selected card (center) */}
      <g aria-hidden="true">
        <rect x={252} y={148} width={136} height={100} rx={4} fill="none" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.40s' }} />
        <rect x={264} y={162} width={80} height={8} rx={2} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.43s' }} />
        <rect x={264} y={178} width={100} height={6} rx={1} fill="var(--m-line)" className="m-draw" pathLength={1} style={{ animationDelay: '0.45s' }} />
        <rect x={264} y={216} width={56} height={18} rx={2} fill="none" stroke="var(--m-line)" strokeWidth={1} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.49s' }} />

        {/* selection rectangle — draw on the rect, pulse on the wrapper group so
            the two animations don't fight over the `animation` shorthand. */}
        <g className="m-pulse" style={{ animationDelay: '2.2s' }}>
          <rect x={244} y={140} width={152} height={116} rx={3} fill="none" stroke="var(--m-accent)" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '0.72s' }} />
        </g>

        {/* corner handles */}
        <rect x={240} y={136} width={8} height={8} rx={1} fill="var(--m-bg-2)" stroke="var(--m-accent)" strokeWidth={2} pathLength={1} className="m-draw" style={{ animationDelay: '0.82s' }} />
        <rect x={392} y={136} width={8} height={8} rx={1} fill="var(--m-bg-2)" stroke="var(--m-accent)" strokeWidth={2} pathLength={1} className="m-draw" style={{ animationDelay: '0.85s' }} />
        <rect x={240} y={252} width={8} height={8} rx={1} fill="var(--m-bg-2)" stroke="var(--m-accent)" strokeWidth={2} pathLength={1} className="m-draw" style={{ animationDelay: '0.88s' }} />
        <rect x={392} y={252} width={8} height={8} rx={1} fill="var(--m-bg-2)" stroke="var(--m-accent)" strokeWidth={2} pathLength={1} className="m-draw" style={{ animationDelay: '0.91s' }} />
      </g>

      {/* Cursor */}
      <g aria-hidden="true" className="m-float">
        <path d="M376 230 L376 260 L384 252 L389 263 L394 261 L389 250 L398 250 Z" fill="var(--m-accent)" stroke="var(--m-bg-2)" strokeWidth={1.5} strokeLinejoin="round" />
      </g>

      {/* Property panel chip */}
      <g aria-hidden="true">
        <rect x={408} y={148} width={118} height={70} rx={5} fill="var(--m-bg-2)" stroke="var(--m-line-2)" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round" pathLength={1} className="m-draw" style={{ animationDelay: '1.0s' }} />
        <text x={420} y={170} fontFamily="var(--m-mono)" fontSize={9} fill="var(--m-fg-dim)">padding</text>
        <rect x={420} y={175} width={36} height={7} rx={2} fill="var(--m-fg-dim)" />
        <text x={420} y={200} fontFamily="var(--m-mono)" fontSize={9} fill="var(--m-fg-dim)">font-size</text>
        <rect x={420} y={205} width={46} height={7} rx={2} fill="var(--m-fg-dim)" />
      </g>

      {/* connector: selection → panel */}
      <line x1={396} y1={183} x2={408} y2={183} stroke="var(--m-accent)" strokeWidth={1} strokeLinecap="round" pathLength={1} className="m-draw" style={{ animationDelay: '1.05s' }} aria-hidden="true" />
    </svg>
  );
}
